// HVAC: psychrometrics, air and water loads, ducts, fans, pumps, and refrigerants. Registered into the main
// builtin table by builtins.ts. Inputs are US units (°F, ft, CFM, psig) unless the last input is "SI".
// Moist-air equations are from the 2017 ASHRAE Handbook of Fundamentals, chapter 1, as PsychroLib implements them.
// Refrigerant tables are in refrigerants-data.ts, generated by scripts/build-hvac-data.py.
import { fail } from './errors';
import type { Builtin, Def } from './builtin-types';
import { type Value, type RecordRow, num, nums, list, record as plainRecord, text, mapNum, pos, typeName } from './values';
import { REFRIGERANTS, REF_T_MIN, REF_SAT_STEP, REF_GAS_STEP, REF_SUPERHEATS, REF_PSI as PSI, REF_ATM, REF_KGM3_PER_LBFT3, type RefData } from './refrigerants-data';

const ATM_KPA = 101.325;
/** kW of cooling in one ton of refrigeration. */
const KW_PER_TON = 3.516853;
/** Btu/h in one watt. */
const BTUH_PER_W = 3.41214;
/** Standard-air load: Btu/h per CFM·°F, or W per L/s·°C in SI. */
const sensibleCoef = (si: boolean): number => (si ? 1.23 : 1.08);
/** Water load: Btu/h per GPM·°F, or kW per L/s·°C in SI. */
const waterCoef = (si: boolean): number => (si ? 4.19 : 500);

function withUnits(min: number, max: number, usage: string, fn: (a: Value[], si: boolean) => Value): Builtin {
  return {
    min, max: max + 1, usage, fn: (a) => {
      const last = a[a.length - 1];
      if (typeof last !== 'object' || last.t !== 'text') {
        if (a.length > max) fail(`Too many inputs: ${usage}`);
        return fn(a, false);
      }
      const unit = last.s.trim().toUpperCase();
      if (unit !== 'SI' && unit !== 'IP') fail(`Units must be "SI" or "IP", got "${last.s}"`);
      if (a.length - 1 < min) fail(`Too few inputs: ${usage}`);
      return fn(a.slice(0, -1), unit === 'SI');
    },
  };
}

/** A share given as 50, 50%, or 0.5. At 1 or below it's a fraction, because 50% reaches a function as 0.5. */
const shareOf = (x: number): number => (x <= 1 ? x : x / 100);

function rhFraction(x: number): number {
  if (!(x >= 0 && x <= 100)) fail(`Relative humidity must be from 0 to 100%, got ${x}`);
  return shareOf(x);
}

function efficiency(v: Value | undefined, what: string): number {
  if (v === undefined) return 1;
  const x = num(v, what);
  if (!(x > 0 && x <= 100)) fail(`${what} must be above 0 and at most 100%, got ${x}`);
  return shareOf(x);
}

const altitudeArg = (v: Value | undefined): number => (v === undefined ? 0 : num(v, 'Altitude'));

function map2(a: Value, b: Value, f: (x: number, y: number) => number, what: string): Value {
  if (typeof a === 'object' && a.t === 'list') {
    if (typeof b === 'object' && b.t === 'list') {
      if (a.items.length !== b.items.length) fail(`${what} needs lists of the same length (got ${a.items.length} and ${b.items.length})`);
      return list(a.items.map((x, i) => map2(x, b.items[i], f, what)));
    }
    return list(a.items.map((x) => map2(x, b, f, what)));
  }
  if (typeof b === 'object' && b.t === 'list') return list(b.items.map((y) => map2(a, y, f, what)));
  return f(num(a, what), num(b, what));
}

const round = (x: number, places: number): number => {
  const k = 10 ** places;
  const r = Math.round(x * k) / k;
  return r === 0 ? 0 : r;
};

const rows = (...r: [string, number][]): RecordRow[] => r.map(([label, value]) => ({ label, value }));

const record = (title: string, r: RecordRow[]): Value => ({ ...plainRecord(title, r), decimal: true });

const MIN_W = 1e-7;

/** The temperatures the moist-air equations cover. */
const moistAirRange = (si: boolean): [number, number] => (si ? [-100, 200] : [-148, 392]);

function checkDb(t: number, si: boolean): void {
  const [lo, hi] = moistAirRange(si);
  if (!(t >= lo && t <= hi)) fail(`Temperature must be from ${lo} to ${hi} ${si ? '°C' : '°F'} for moist air, got ${t}`);
}

/** Saturation pressure of water: psia, or kPa in SI. Over ice below the triple point. */
function satPressure(t: number, si: boolean): number {
  checkDb(t, si);
  if (si) {
    const T = t + 273.15;
    const ln = t <= 0.01
      ? -5.6745359e3 / T + 6.3925247 - 9.677843e-3 * T + 6.2215701e-7 * T ** 2 + 2.0747825e-9 * T ** 3 - 9.484024e-13 * T ** 4 + 4.1635019 * Math.log(T)
      : -5.8002206e3 / T + 1.3914993 - 4.8640239e-2 * T + 4.1764768e-5 * T ** 2 - 1.4452093e-8 * T ** 3 + 6.5459673 * Math.log(T);
    return Math.exp(ln) / 1000;
  }
  const T = t + 459.67;
  const ln = t <= 32.018
    ? -1.0214165e4 / T - 4.8932428 - 5.3765794e-3 * T + 1.9202377e-7 * T ** 2 + 3.5575832e-10 * T ** 3 - 9.0344688e-14 * T ** 4 + 4.1635019 * Math.log(T)
    : -1.0440397e4 / T - 1.129465e1 - 2.7022355e-2 * T + 1.289036e-5 * T ** 2 - 2.4780681e-9 * T ** 3 + 6.5459673 * Math.log(T);
  return Math.exp(ln);
}

/** Standard-atmosphere pressure at an altitude in ft (psia), or m in SI (kPa). */
function pressureAt(alt: number, si: boolean): number {
  const base = 1 - (si ? 2.25577e-5 : 6.8754e-6) * alt;
  if (!(base > 0)) fail(`Altitude ${alt} ${si ? 'm' : 'ft'} is above the standard atmosphere`);
  return (si ? ATM_KPA : REF_ATM) * base ** 5.2559;
}

const humRatioFromVp = (vp: number, p: number): number => {
  if (!(vp < p)) fail('Water would boil at this temperature and pressure, so moist air has no humidity ratio here');
  return Math.max((0.621945 * vp) / (p - vp), MIN_W);
};

const satHumRatio = (t: number, p: number, si: boolean): number => humRatioFromVp(satPressure(t, si), p);

const humRatioFromRh = (t: number, rh: number, p: number, si: boolean): number => humRatioFromVp(rh * satPressure(t, si), p);

const vaporPressure = (w: number, p: number): number => (p * w) / (0.621945 + w);

const enthalpyOf = (t: number, w: number, si: boolean): number => (si ? 1.006 * t + w * (2501 + 1.86 * t) : 0.24 * t + w * (1061 + 0.444 * t));

/** Volume per unit mass of dry air: ft³/lb, or m³/kg in SI. */
const volumeOf = (t: number, w: number, p: number, si: boolean): number =>
  si ? (0.287042 * (t + 273.15) * (1 + 1.607858 * w)) / p : (53.35 * (t + 459.67) * (1 + 1.607858 * w)) / (144 * p);

const densityOf = (t: number, w: number, p: number, si: boolean): number => (1 + w) / volumeOf(t, w, p, si);

const dryBulbFrom = (h: number, w: number, si: boolean): number => (si ? (h - 2501 * w) / (1.006 + 1.86 * w) : (h - 1061 * w) / (0.24 + 0.444 * w));

function dewPointOf(vp: number, si: boolean): number {
  const [lo, hi] = moistAirRange(si);
  if (vp < satPressure(lo, si)) fail(`There is too little water vapor for a dew point above ${lo} ${si ? '°C' : '°F'}`);
  const ln = Math.log(vp);
  // Bisection on a monotonic curve. Each step halves the bracket, and 50 steps reach far below a displayed digit.
  let a = lo, b = hi;
  for (let k = 0; k < 60; k++) {
    const m = (a + b) / 2;
    if (Math.log(satPressure(m, si)) < ln) a = m;
    else b = m;
  }
  return (a + b) / 2;
}

const dewPointFromVp = (t: number, vp: number, si: boolean): number => Math.min(dewPointOf(vp, si), t);

function checkDewPoint(dp: number, t: number): void {
  if (dp > t + 1e-9) fail(`Dew point (${dp}) can't be above dry bulb (${t})`);
}

function humRatioFromWb(t: number, wb: number, p: number, si: boolean): number {
  if (wb > t + 1e-9) fail(`Wet bulb (${round(wb, 3)}) can't be above dry bulb (${round(t, 3)})`);
  const ws = satHumRatio(wb, p, si);
  let w: number;
  if (si) {
    w = wb >= 0
      ? ((2501 - 2.326 * wb) * ws - 1.006 * (t - wb)) / (2501 + 1.86 * t - 4.186 * wb)
      : ((2830 - 0.24 * wb) * ws - 1.006 * (t - wb)) / (2830 + 1.86 * t - 2.1 * wb);
  } else {
    w = wb >= 32
      ? ((1093 - 0.556 * wb) * ws - 0.24 * (t - wb)) / (1093 + 0.444 * t - wb)
      : ((1220 - 0.04 * wb) * ws - 0.24 * (t - wb)) / (1220 + 0.444 * t - 0.48 * wb);
  }
  return Math.max(w, MIN_W);
}

function wetBulbFromW(t: number, w: number, p: number, si: boolean): number {
  const bounded = Math.max(w, MIN_W);
  let lo = dewPointFromVp(t, vaporPressure(bounded, p), si), hi = t;
  for (let k = 0; k < 60 && hi - lo > 1e-10; k++) {
    const m = (lo + hi) / 2;
    if (humRatioFromWb(t, m, p, si) > bounded) hi = m;
    else lo = m;
  }
  return (lo + hi) / 2;
}

const rhFromW = (t: number, w: number, p: number, si: boolean): number => vaporPressure(w, p) / satPressure(t, si);

function airRecord(title: string, t: number, w: number, p: number, si: boolean): Value {
  const vp = vaporPressure(w, p);
  const rh = vp / satPressure(t, si);
  const r = rows(
    [`Dry bulb (${si ? '°C' : '°F'})`, round(t, 2)],
    [`Wet bulb (${si ? '°C' : '°F'})`, round(rh > 1 ? t : wetBulbFromW(t, w, p, si), 2)],
    [`Dew point (${si ? '°C' : '°F'})`, round(rh > 1 ? dewPointOf(vp, si) : dewPointFromVp(t, vp, si), 2)],
    ['Relative humidity (%)', round(rh * 100, 2)],
    [si ? 'Humidity ratio (kg/kg)' : 'Humidity ratio (lb/lb)', round(w, 6)],
    [si ? 'Moisture (g/kg)' : 'Moisture (gr/lb)', round(w * (si ? 1000 : 7000), 2)],
    [si ? 'Enthalpy (kJ/kg dry air)' : 'Enthalpy (Btu/lb dry air)', round(enthalpyOf(t, w, si), si ? 2 : 3)],
    [si ? 'Volume (m³/kg dry air)' : 'Volume (ft³/lb dry air)', round(volumeOf(t, w, p, si), si ? 4 : 3)],
    [si ? 'Density (kg/m³)' : 'Density (lb/ft³)', round(densityOf(t, w, p, si), si ? 4 : 5)],
    [si ? 'Vapor pressure (kPa)' : 'Vapor pressure (psia)', round(vp, si ? 3 : 4)],
    [si ? 'Air pressure (kPa)' : 'Air pressure (psia)', round(p, si ? 2 : 3)],
  );
  return record(rh > 1.000001 ? `${title}: above saturation, so water or fog forms` : title, r);
}

type StateBy = (t: number, x: number, p: number, si: boolean) => number;

const byRh: StateBy = (t, rh, p, si) => humRatioFromRh(t, rhFraction(rh), p, si);
const byWb: StateBy = (t, wb, p, si) => humRatioFromWb(t, wb, p, si);
const byDp: StateBy = (t, dp, p, si) => {
  checkDewPoint(dp, t);
  return humRatioFromVp(satPressure(dp, si), p);
};
const byW: StateBy = (_t, w) => {
  if (!(w >= 0)) fail(`Humidity ratio can't be negative, got ${w}`);
  return Math.max(w, MIN_W);
};
const byH: StateBy = (t, h, _p, si) => {
  const w = si ? (h - 1.006 * t) / (2501 + 1.86 * t) : (h - 0.24 * t) / (1061 + 0.444 * t);
  if (w < 0) fail(`Enthalpy ${h} is below dry air at this temperature`);
  return Math.max(w, MIN_W);
};

function psychFn(usage: string, by: StateBy, title: (a: number, b: number, si: boolean) => string): Builtin {
  return withUnits(2, 3, usage, (a, si) => {
    const t = num(a[0], 'Dry bulb'), x = num(a[1], 'Second property');
    checkDb(t, si);
    const p = pressureAt(altitudeArg(a[2]), si);
    return airRecord(title(t, x, si), t, by(t, x, p, si), p, si);
  });
}

function airScalar(usage: string, what: string, f: (t: number, w: number, p: number, si: boolean) => number): Builtin {
  return withUnits(2, 3, usage, (a, si) => {
    const p = pressureAt(altitudeArg(a[2]), si);
    return map2(a[0], a[1], (t, rh) => f(t, humRatioFromRh(t, rhFraction(rh), p, si), p, si), what);
  });
}

/** How much thinner the air is at an altitude, compared to sea level. Standard-air coefficients scale by this. */
const altitudeFactor = (v: Value | undefined, si: boolean): number => pressureAt(altitudeArg(v), si) / pressureAt(0, si);

function coilRecord(cfm: number, t1: number, w1: number, t2: number, w2: number, alt: Value | undefined, si: boolean): Value {
  const p = pressureAt(altitudeArg(alt), si);
  const v1 = volumeOf(t1, w1, p, si);
  const dryRate = si ? cfm / 1000 / v1 : (60 * cfm) / v1; // kg/s, or lb/h
  const condensing = Math.max(w1 - w2, 0);
  const liquid = si ? 4.186 * t2 : t2 - 32; // enthalpy of the condensate leaving
  const total = dryRate * (enthalpyOf(t1, w1, si) - enthalpyOf(t2, w2, si) - condensing * liquid);
  const sensible = dryRate * (enthalpyOf(t1, w2, si) - enthalpyOf(t2, w2, si));
  const latent = total - sensible;
  const tons = si ? total / KW_PER_TON : total / 12000;
  const water = dryRate * condensing * (si ? 3600 : 1 / 8.3454);
  return record(total >= 0 ? 'Coil: air cooled' : 'Coil: air heated', rows(
    [si ? 'Total (kW)' : 'Total (Btu/h)', round(total, si ? 3 : 0)],
    [si ? 'Sensible (kW)' : 'Sensible (Btu/h)', round(sensible, si ? 3 : 0)],
    [si ? 'Latent (kW)' : 'Latent (Btu/h)', round(latent, si ? 3 : 0)],
    ['Tons', round(tons, 2)],
    ['Sensible heat ratio', total === 0 ? NaN : round(sensible / total, 3)],
    [si ? 'Condensate (L/h)' : 'Condensate (gal/h)', round(water, 2)],
    [si ? 'Enthalpy drop (kJ/kg)' : 'Enthalpy drop (Btu/lb)', round(enthalpyOf(t1, w1, si) - enthalpyOf(t2, w2, si), si ? 2 : 3)],
  ));
}

function coilFn(usage: string, by: StateBy): Builtin {
  return withUnits(5, 6, usage, (a, si) => {
    const [flow, t1, x1, t2, x2] = a.slice(0, 5).map((v, i) => num(v, ['Airflow', 'Entering dry bulb', 'Entering humidity', 'Leaving dry bulb', 'Leaving humidity'][i]));
    pos(flow, 'Airflow');
    const p = pressureAt(altitudeArg(a[5]), si);
    return coilRecord(flow, t1, by(t1, x1, p, si), t2, by(t2, x2, p, si), a[5], si);
  });
}

const STD_RHO = { ip: 1.2014, si: 1.204 }; // kg/m³: 0.075 lb/ft³ and the ASHRAE SI value
const AIR_NU = 1.516e-5; // m²/s
const GALV_ROUGHNESS = 9e-5; // m, galvanized steel with longitudinal seams
const IN_WC = 249.089; // Pa

/** Pressure loss in Pa/m for air in a round duct, by Darcy and Colebrook. */
function darcyLoss(flowM3: number, dM: number, rho: number): number {
  const v = flowM3 / ((Math.PI / 4) * dM * dM);
  const re = (v * dM) / AIR_NU;
  let f = re < 2300 ? 64 / re : 0.02;
  if (re >= 2300) {
    for (let k = 0; k < 40; k++) {
      const next = (-2 * Math.log10(GALV_ROUGHNESS / dM / 3.7 + 2.51 / (re * Math.sqrt(f)))) ** -2;
      if (Math.abs(next - f) < 1e-12) { f = next; break; }
      f = next;
    }
  }
  return ((f / dM) * rho * v * v) / 2;
}

const eqDiameter = (a: number, b: number): number => (1.3 * (a * b) ** 0.625) / (a + b) ** 0.25;

function ductDiameter(a: Value[]): number {
  const first = pos(num(a[1], 'Duct size'), 'Duct size');
  return a.length > 2 ? eqDiameter(first, pos(num(a[2], 'Duct size'), 'Duct size')) : first;
}

const toM3 = (q: number, si: boolean): number => (si ? q / 1000 : q * 0.3048 ** 3 / 60);
const toM = (d: number, si: boolean): number => (si ? d / 1000 : d * 0.0254);
/** Pa/m → the display unit: Pa/m, or in. w.c. per 100 ft. */
const lossOut = (l: number, si: boolean): number => (si ? l : (l * 30.48) / IN_WC);
const rhoFor = (si: boolean): number => (si ? STD_RHO.si : STD_RHO.ip);

/** A value from a uniform grid by four-point Lagrange interpolation. */
function cubic(y: number[], pos: number): number {
  const i = Math.max(0, Math.min(y.length - 4, Math.floor(pos) - 1));
  const t = pos - i;
  const [a, b, c, d] = [y[i], y[i + 1], y[i + 2], y[i + 3]];
  return (
    (a * -(t - 1) * (t - 2) * (t - 3)) / 6 +
    (b * t * (t - 2) * (t - 3)) / 2 -
    (c * t * (t - 1) * (t - 3)) / 2 +
    (d * t * (t - 1) * (t - 2)) / 6
  );
}

function cubicAt(xs: number[], y: number[], x: number): number {
  let i = 0;
  while (i < xs.length - 4 && x > xs[i + 2]) i++;
  let r = 0;
  for (let j = i; j < i + 4; j++) {
    let l = y[j];
    for (let k = i; k < i + 4; k++) if (k !== j) l *= (x - xs[k]) / (xs[j] - xs[k]);
    r += l;
  }
  return r;
}

const canonicalRef = (s: string): string => s.toLowerCase().replace(/[^a-z0-9]/g, '').replace(/^r(?=\d)/, '');

const REF_INDEX = new Map<string, RefData>();
for (const r of REFRIGERANTS) {
  REF_INDEX.set(canonicalRef(r.name), r);
  for (const a of r.aka) REF_INDEX.set(canonicalRef(a), r);
}

const refNames = (): string => REFRIGERANTS.map((r) => r.name).join(', ');

function refArg(v: Value): RefData {
  if (typeof v !== 'object' || v.t !== 'text') fail(`The refrigerant goes first, in quotes, like "R410A"; got a ${typeName(v)}`);
  const r = REF_INDEX.get(canonicalRef(v.s));
  if (!r) fail(`No table for refrigerant "${v.s}". Available: ${refNames()}`);
  return r;
}

const toF = (t: number, si: boolean): number => (si ? (t * 9) / 5 + 32 : t);
const fromF = (f: number, si: boolean): number => (si ? ((f - 32) * 5) / 9 : f);
const KJKG_PER_BTULB = 2.326;

function satPos(r: RefData, f: number): number {
  if (!(f >= REF_T_MIN && f <= r.top + 1e-9)) {
    fail(`${r.name}'s table runs from ${REF_T_MIN} to ${r.top} °F (${round(fromF(REF_T_MIN, true), 1)} to ${round(fromF(r.top, true), 1)} °C), and it's critical at ${r.tc} °F; got ${round(f, 2)} °F`);
  }
  return (f - REF_T_MIN) / REF_SAT_STEP;
}

/** Absolute saturation pressure in kPa. Log pressure is close to a straight line in temperature, so it interpolates well. */
function satKpa(r: RefData, f: number, dew: boolean): number {
  const y = dew && r.pd ? r.pd : r.pb;
  logCache.set(y, logCache.get(y) ?? y.map(Math.log));
  return Math.exp(cubic(logCache.get(y)!, satPos(r, f)));
}
const logCache = new Map<number[], number[]>();

/** The saturation temperature in °F at an absolute pressure in kPa. */
function satF(r: RefData, kpa: number, dew: boolean): number {
  const y = dew && r.pd ? r.pd : r.pb;
  const lo = y[0], hi = y[y.length - 1];
  if (!(kpa >= lo && kpa <= hi)) {
    fail(`${r.name}'s table covers ${round(lo / PSI - REF_ATM, 1)} to ${round(hi / PSI - REF_ATM, 1)} psig (${round(lo - ATM_KPA, 0)} to ${round(hi - ATM_KPA, 0)} kPa gauge); this pressure is ${round(kpa / PSI - REF_ATM, 1)} psig`);
  }
  let a = REF_T_MIN, b = r.top;
  for (let k = 0; k < 50; k++) {
    const m = (a + b) / 2;
    if (satKpa(r, m, dew) < kpa) a = m;
    else b = m;
  }
  return (a + b) / 2;
}

/** Local atmosphere in kPa, so gauge pressures work at altitude. */
const atmKpa = (alt: Value | undefined, si: boolean): number => (si ? pressureAt(altitudeArg(alt), true) : pressureAt(altitudeArg(alt), false) * PSI);
const gaugeToAbs = (p: number, atm: number, si: boolean): number => (si ? p + atm : p * PSI + atm);
const absToGauge = (kpa: number, atm: number, si: boolean): number => (si ? kpa - atm : (kpa - atm) / PSI);

/** Saturation at a temperature: pressures, then liquid and vapor properties in table units. */
function satState(r: RefData, f: number) {
  const pos = satPos(r, f);
  return {
    pb: satKpa(r, f, false), pd: satKpa(r, f, true),
    hl: cubic(r.hl, pos), hv: cubic(r.hv, pos),
    sl: cubic(r.sl, pos), sv: cubic(r.sv, pos),
    dl: cubic(r.dl, pos), vv: Math.exp(cubic(r.vv.map(Math.log), pos)),
  };
}

const gasRows = (r: RefData): number => r.gh.length;
const gasTop = (r: RefData): number => REF_T_MIN + (gasRows(r) - 1) * REF_GAS_STEP;
const MAX_SUPERHEAT = REF_SUPERHEATS[REF_SUPERHEATS.length - 1];

/** A superheated vapor property from a table, at a dew point (°F) and the °F above it. */
function gas(table: number[][], dewF: number, sh: number): number {
  return cubic(table.map((row) => cubicAt(REF_SUPERHEATS, row, sh)), (dewF - REF_T_MIN) / REF_GAS_STEP);
}

function superheatWhere(table: number[][], dewF: number, target: number): number {
  let a = 0, b = MAX_SUPERHEAT;
  for (let k = 0; k < 50; k++) {
    const m = (a + b) / 2;
    if (gas(table, dewF, m) < target) a = m;
    else b = m;
  }
  return (a + b) / 2;
}

function dischargeTooHigh(r: RefData): never {
  return fail(`Discharge from this cycle would be more than ${MAX_SUPERHEAT} °F above the dew point, past the end of ${r.name}'s vapor table`);
}

/** One vapor-compression cycle in table units. Evaporating is a dew point and condensing a bubble point, both °F. */
function cycle(r: RefData, te: number, tc: number, sh: number, sc: number, eta: number) {
  if (!(sh >= 0)) fail(`Superheat can't be negative, got ${sh}`);
  if (!(sc >= 0)) fail(`Subcooling can't be negative, got ${sc}`);
  if (!(te < tc)) fail(`Evaporating (${round(te, 1)} °F) must be below condensing (${round(tc, 1)} °F)`);
  satPos(r, te);
  satPos(r, tc - sc);
  const pc = satKpa(r, tc, false);
  const dewC = satF(r, pc, true);
  if (tc > r.top - 3) fail(`${r.name} condensing at ${round(tc, 1)} °F is too close to the end of its table (${r.top} °F, critical ${r.tc} °F)`);
  if (dewC > gasTop(r) || te > gasTop(r)) fail(`${r.name}'s vapor table stops at ${gasTop(r)} °F, below this condensing temperature`);
  if (sh > MAX_SUPERHEAT) fail(`Superheat is limited to ${MAX_SUPERHEAT} °F, got ${sh}`);
  const h1 = gas(r.gh, te, sh), s1 = gas(r.gs, te, sh), v1 = Math.exp(gas(r.gv.map((row) => row.map(Math.log)), te, sh));
  const h3 = cubic(r.hl, satPos(r, tc - sc));
  const satS = gas(r.gs, dewC, 0), satH = gas(r.gh, dewC, 0);
  let h2s: number;
  if (s1 >= satS) {
    if (s1 > gas(r.gs, dewC, MAX_SUPERHEAT)) dischargeTooHigh(r);
    h2s = gas(r.gh, dewC, superheatWhere(r.gs, dewC, s1));
  } else {
    // Fluids like R-600a can finish compression still wet: follow entropy back from saturated vapor.
    h2s = satH - ((dewC + 459.67) * 5 / 9) * (satS - s1);
  }
  const w = (h2s - h1) / eta;
  const h2 = h1 + w;
  if (h2 > gas(r.gh, dewC, MAX_SUPERHEAT)) dischargeTooHigh(r);
  const dischargeF = dewC + (h2 > satH ? superheatWhere(r.gh, dewC, h2) : 0);
  return { pe: satKpa(r, te, true), pc, h1, h3, h2, w, q: h1 - h3, v1, dischargeF };
}

export function registerHvac(def: Def): void {
  // Moist air
  def('psych', psychFn('psych(db, rh, alt): moist air from dry bulb (°F) and %RH (50 or 0.5: 1 or less is read as a fraction), at an altitude in ft if given. Last input "SI" for °C and m', byRh, (t, x, si) => `Moist air at ${t} ${si ? '°C' : '°F'}, ${round(rhFraction(x) * 100, 2)}% RH`));
  def('psychwb', psychFn('psychwb(db, wb, alt): moist air from dry bulb and wet bulb. Last input "SI" for °C and m', byWb, (t, x, si) => `Moist air at ${t} ${si ? '°C' : '°F'} dry bulb, ${x} wet bulb`));
  def('psychdp', psychFn('psychdp(db, dp, alt): moist air from dry bulb and dew point. Last input "SI" for °C and m', byDp, (t, x, si) => `Moist air at ${t} ${si ? '°C' : '°F'} dry bulb, ${x} dew point`));
  def('psychw', psychFn('psychw(db, w, alt): moist air from dry bulb and humidity ratio in lb/lb. Last input "SI" for °C, kg/kg and m', byW, (t, x, si) => `Moist air at ${t} ${si ? '°C' : '°F'}, humidity ratio ${x}`));
  def('psychh', psychFn('psychh(db, h, alt): moist air from dry bulb and enthalpy in Btu/lb. Last input "SI" for °C, kJ/kg and m', byH, (t, x, si) => `Moist air at ${t} ${si ? '°C' : '°F'}, enthalpy ${x}`));
  def('enthalpy', airScalar('enthalpy(db, rh, alt): moist air enthalpy, Btu/lb dry air, with 0 at 0 °F dry air. Last input "SI" for kJ/kg, with 0 at 0 °C', 'enthalpy', (t, w, _p, si) => enthalpyOf(t, w, si)));
  def('wetbulb', airScalar('wetbulb(db, rh, alt): wet bulb in °F. Last input "SI" for °C', 'wetbulb', (t, w, p, si) => wetBulbFromW(t, w, p, si)));
  def('humratio', airScalar('humratio(db, rh, alt): humidity ratio in lb water/lb dry air. Last input "SI" for kg/kg', 'humratio', (_t, w) => w));
  def('grains', airScalar('grains(db, rh, alt): moisture in grains/lb dry air. Last input "SI" for g/kg', 'grains', (_t, w, _p, si) => w * (si ? 1000 : 7000)));
  def('specvol', airScalar('specvol(db, rh, alt): volume in ft³/lb dry air. Last input "SI" for m³/kg', 'specvol', (t, w, p, si) => volumeOf(t, w, p, si)));
  def('airdensity', airScalar('airdensity(db, rh, alt): moist air density in lb/ft³. Last input "SI" for kg/m³', 'airdensity', (t, w, p, si) => densityOf(t, w, p, si)));
  def('dewpoint', withUnits(2, 2, 'dewpoint(db, rh): dew point in °F. Last input "SI" for °C', (a, si) =>
    map2(a[0], a[1], (t, rhIn) => {
      const rh = rhFraction(rhIn);
      if (rh === 0) fail('Dry air (0% RH) has no dew point');
      return dewPointFromVp(t, rh * satPressure(t, si), si);
    }, 'dewpoint')));
  def('rhfromwb', withUnits(2, 3, 'rhfromwb(db, wb, alt): %RH from dry bulb and wet bulb. Last input "SI" for °C and m', (a, si) => {
    const p = pressureAt(altitudeArg(a[2]), si);
    return map2(a[0], a[1], (t, wb) => rhFromW(t, humRatioFromWb(t, wb, p, si), p, si) * 100, 'rhfromwb');
  }));
  def('rhfromdp', withUnits(2, 2, 'rhfromdp(db, dp): %RH from dry bulb and dew point. Last input "SI" for °C', (a, si) =>
    map2(a[0], a[1], (t, dp) => {
      checkDewPoint(dp, t);
      return (satPressure(dp, si) / satPressure(t, si)) * 100;
    }, 'rhfromdp')));
  def('psat', withUnits(1, 1, 'psat(t): saturation pressure of water in psia at t °F. Last input "SI" for kPa at t °C', (a, si) => mapNum(a[0], (t) => satPressure(t, si), 'psat')));
  def('altpressure', withUnits(1, 1, 'altpressure(alt): standard air pressure in psia at an altitude in ft. Last input "SI" for kPa and m', (a, si) => mapNum(a[0], (z) => pressureAt(z, si), 'altpressure')));

  // Mixing
  def('mixair', withUnits(6, 7, 'mixair(q1, db1, rh1, q2, db2, rh2, alt): two airstreams mixed by mass, flows in CFM. Last input "SI" for L/s, °C and m', (a, si) => {
    const [q1, t1, rh1, q2, t2, rh2] = a.slice(0, 6).map((v) => num(v, 'mixair input'));
    pos(q1 + q2, 'Total airflow');
    if (q1 < 0 || q2 < 0) fail('Airflows must not be negative');
    const p = pressureAt(altitudeArg(a[6]), si);
    const w1 = humRatioFromRh(t1, rhFraction(rh1), p, si), w2 = humRatioFromRh(t2, rhFraction(rh2), p, si);
    const m1 = q1 / volumeOf(t1, w1, p, si), m2 = q2 / volumeOf(t2, w2, p, si);
    const w = (m1 * w1 + m2 * w2) / (m1 + m2);
    const h = (m1 * enthalpyOf(t1, w1, si) + m2 * enthalpyOf(t2, w2, si)) / (m1 + m2);
    return airRecord(`Mixed air, ${round((q2 / (q1 + q2)) * 100, 1)}% from stream 2`, dryBulbFrom(h, w, si), w, p, si);
  }));
  def('mixtemp', { min: 4, max: 4, usage: 'mixtemp(t1, q1, t2, q2): mixed temperature, weighted by flow', fn: (a) => {
    const [t1, q1, t2, q2] = a.map((v) => num(v, 'mixtemp input'));
    pos(q1 + q2, 'Total flow');
    return (t1 * q1 + t2 * q2) / (q1 + q2);
  } });
  def('oapercent', { min: 3, max: 3, usage: 'oapercent(ma, ra, oa): percent outdoor air from mixed, return and outdoor temperatures', fn: (a) => {
    const [ma, ra, oa] = a.map((v) => num(v, 'oapercent input'));
    if (ra === oa) fail('Return and outdoor air are the same temperature, so temperatures can\'t show the mix');
    return ((ra - ma) / (ra - oa)) * 100;
  } });

  // Loads
  def('sensibleheat', withUnits(2, 3, 'sensibleheat(cfm, dt, alt) = 1.08·CFM·ΔT in Btu/h. Last input "SI": 1.23·L/s·ΔT in W', (a, si) => {
    const k = sensibleCoef(si) * altitudeFactor(a[2], si);
    return map2(a[0], a[1], (q, dt) => k * q * dt, 'sensibleheat');
  }));
  def('latentheat', withUnits(2, 3, 'latentheat(cfm, dgr, alt) = 0.68·CFM·Δgrains in Btu/h. Last input "SI": 3.01·L/s·Δ(g/kg) in W', (a, si) => {
    const k = (si ? 3.01 : 0.68) * altitudeFactor(a[2], si);
    return map2(a[0], a[1], (q, d) => k * q * d, 'latentheat');
  }));
  def('totalheat', withUnits(2, 3, 'totalheat(cfm, dh, alt) = 4.5·CFM·Δh in Btu/h, Δh in Btu/lb. Last input "SI": 1.2·L/s·Δh in W, Δh in kJ/kg', (a, si) => {
    const k = (si ? 1.2 : 4.5) * altitudeFactor(a[2], si);
    return map2(a[0], a[1], (q, d) => k * q * d, 'totalheat');
  }));
  def('airflow', withUnits(2, 3, 'airflow(q, dt, alt): CFM to move q Btu/h at a temperature difference. Last input "SI": L/s from W', (a, si) => {
    const k = sensibleCoef(si) * altitudeFactor(a[2], si);
    return map2(a[0], a[1], (q, dt) => {
      if (dt === 0) fail('Division by zero: the temperature difference is 0');
      return q / (k * dt);
    }, 'airflow');
  }));
  def('temprise', withUnits(2, 3, 'temprise(q, cfm, alt): air temperature change from q Btu/h. Last input "SI": W and L/s', (a, si) => {
    const k = sensibleCoef(si) * altitudeFactor(a[2], si);
    return map2(a[0], a[1], (q, flow) => q / (k * pos(flow, 'Airflow')), 'temprise');
  }));
  def('shratio', { min: 2, max: 2, usage: 'shratio(sensible, total) = sensible ÷ total', fn: (a) => {
    const total = num(a[1], 'Total heat');
    if (total === 0) fail('Division by zero: total heat is 0');
    return num(a[0], 'Sensible heat') / total;
  } });
  def('coil', coilFn('coil(cfm, edb, erh, ldb, lrh, alt): coil load from entering and leaving dry bulb and %RH. Last input "SI" for L/s, °C and m', byRh));
  def('coilwb', coilFn('coilwb(cfm, edb, ewb, ldb, lwb, alt): coil load from entering and leaving dry bulb and wet bulb. Last input "SI" for L/s, °C and m', byWb));
  def('bypassfactor', { min: 3, max: 3, usage: 'bypassfactor(edb, ldb, adp) = (ldb − adp)/(edb − adp), with adp the apparatus dew point', fn: (a) => {
    const [e, l, adp] = a.map((v) => num(v, 'bypassfactor input'));
    if (e === adp) fail('Entering air is at the apparatus dew point, so the factor is undefined');
    return (l - adp) / (e - adp);
  } });
  def('waterheat', withUnits(2, 2, 'waterheat(gpm, dt) = 500·GPM·ΔT in Btu/h, for water. Last input "SI": 4.19·L/s·ΔT in kW', (a, si) =>
    map2(a[0], a[1], (q, dt) => waterCoef(si) * q * dt, 'waterheat')));
  def('waterflow', withUnits(2, 2, 'waterflow(q, dt): GPM to carry q Btu/h at a temperature difference. Last input "SI": L/s from kW', (a, si) =>
    map2(a[0], a[1], (q, dt) => {
      if (dt === 0) fail('Division by zero: the temperature difference is 0');
      return q / (waterCoef(si) * dt);
    }, 'waterflow')));
  def('uaheat', { min: 3, max: 3, usage: 'uaheat(u, a, dt) = U·A·ΔT, through a wall or roof', fn: (a) => num(a[0], 'U') * num(a[1], 'Area') * num(a[2], 'ΔT') });
  def('uvalue', { min: 1, max: Infinity, usage: 'uvalue(r1, r2, …) = 1/ΣR, for layers in series', fn: (a) => {
    const total = a.flatMap((v) => nums(v, 'R-values')).reduce((p, q) => p + q, 0);
    return 1 / pos(total, 'Total R-value');
  } });
  def('airchanges', withUnits(2, 2, 'airchanges(cfm, volume): air changes per hour, volume in ft³. Last input "SI" for L/s and m³', (a, si) =>
    map2(a[0], a[1], (q, vol) => ((si ? 3.6 : 60) * q) / pos(vol, 'Volume'), 'airchanges')));
  def('achflow', withUnits(2, 2, 'achflow(ach, volume): CFM for a number of air changes per hour, volume in ft³. Last input "SI" for L/s and m³', (a, si) =>
    map2(a[0], a[1], (ach, vol) => (ach * pos(vol, 'Volume')) / (si ? 3.6 : 60), 'achflow')));
  def('ventair', { min: 4, max: 4, usage: 'ventair(people, rp, area, ra) = Rp·people + Ra·area, the ASHRAE 62.1 breathing zone flow', fn: (a) => num(a[1], 'Rp') * num(a[0], 'People') + num(a[3], 'Ra') * num(a[2], 'Area') });

  // Ducts and airflow
  def('ductvel', withUnits(2, 3, 'ductvel(cfm, d) or ductvel(cfm, w, h): air velocity in FPM, sizes in inches. Last input "SI" for L/s, mm and m/s', (a, si) => {
    const q = num(a[0], 'Airflow');
    const area = a.length > 2 ? pos(num(a[1], 'Width'), 'Width') * pos(num(a[2], 'Height'), 'Height') : (Math.PI / 4) * pos(num(a[1], 'Diameter'), 'Diameter') ** 2;
    return si ? (q / 1000) / (area / 1e6) : q / (area / 144);
  }));
  def('ductloss', withUnits(2, 3, 'ductloss(cfm, d) or ductloss(cfm, w, h): friction in in. w.c. per 100 ft, galvanized duct, standard air. Last input "SI" for L/s, mm and Pa/m', (a, si) => {
    const q = pos(num(a[0], 'Airflow'), 'Airflow');
    return lossOut(darcyLoss(toM3(q, si), toM(ductDiameter(a), si), rhoFor(si)), si);
  }));
  def('ductsize', withUnits(2, 2, 'ductsize(cfm, loss): round duct in inches for a friction rate, in. w.c. per 100 ft. Last input "SI" for L/s, Pa/m and mm', (a, si) => {
    const q = toM3(pos(num(a[0], 'Airflow'), 'Airflow'), si);
    const target = pos(num(a[1], 'Friction rate'), 'Friction rate');
    let lo = 1e-3, hi = 100;
    for (let k = 0; k < 80; k++) {
      const m = Math.sqrt(lo * hi);
      if (lossOut(darcyLoss(q, m, rhoFor(si)), si) > target) lo = m;
      else hi = m;
    }
    const d = Math.sqrt(lo * hi);
    return si ? d * 1000 : d / 0.0254;
  }));
  def('ductdia', withUnits(2, 2, 'ductdia(cfm, fpm): round duct in inches for an air velocity. Last input "SI" for L/s, m/s and mm', (a, si) =>
    map2(a[0], a[1], (q, v) => {
      const area = si ? (q / 1000 / pos(v, 'Velocity')) * 1e6 : (q / pos(v, 'Velocity')) * 144;
      return Math.sqrt((4 * area) / Math.PI);
    }, 'ductdia')));
  def('eqdia', { min: 2, max: 2, usage: 'eqdia(w, h) = 1.30(wh)^0.625/(w + h)^0.25, the round duct with the same friction', fn: (a) => eqDiameter(pos(num(a[0], 'Width'), 'Width'), pos(num(a[1], 'Height'), 'Height')) });
  def('rectduct', { min: 2, max: 2, usage: 'rectduct(d, w): the other side of a rectangular duct equal to round size d', fn: (a) => {
    const d = pos(num(a[0], 'Diameter'), 'Diameter'), w = pos(num(a[1], 'Width'), 'Width');
    let lo = 1e-6 * d, hi = 1e6 * d;
    for (let k = 0; k < 120; k++) {
      const m = Math.sqrt(lo * hi);
      if (eqDiameter(w, m) < d) lo = m;
      else hi = m;
    }
    return Math.sqrt(lo * hi);
  } });
  def('velpressure', withUnits(1, 1, 'velpressure(fpm) = (V/4005)², in. w.c., standard air. Last input "SI": 0.602·V² in Pa, V in m/s', (a, si) =>
    mapNum(a[0], (v) => (si ? 0.602 * v * v : (v / 4005) ** 2), 'velpressure')));
  def('velfromvp', withUnits(1, 1, 'velfromvp(vp) = 4005√vp in FPM, for a pitot reading in in. w.c. Last input "SI": m/s from Pa', (a, si) =>
    mapNum(a[0], (p) => {
      if (p < 0) fail(`Velocity pressure can't be negative, got ${p}`);
      return si ? Math.sqrt(p / 0.602) : 4005 * Math.sqrt(p);
    }, 'velfromvp')));
  def('fanlaws', { min: 5, max: 5, usage: 'fanlaws(flow, pressure, power, rpm1, rpm2): flow scales with speed, pressure with speed², power with speed³', fn: (a) => {
    const [q, sp, bhp, n1, n2] = a.map((v) => num(v, 'fanlaws input'));
    const r = n2 / pos(n1, 'Starting speed');
    return record(`Fan or pump at ${n2} rpm`, rows(['Flow', q * r], ['Pressure or head', sp * r * r], ['Power', bhp * r * r * r]));
  } });
  def('fanpower', withUnits(2, 3, 'fanpower(cfm, sp, eff) = CFM·SP/(6356·eff) in BHP, SP in in. w.c. Last input "SI": kW from L/s and Pa', (a, si) => {
    const eff = efficiency(a[2], 'Fan efficiency');
    return map2(a[0], a[1], (q, p) => (si ? (q * p) / (1e6 * eff) : (q * p) / (6356 * eff)), 'fanpower');
  }));
  def('pumppower', withUnits(2, 4, 'pumppower(gpm, head, eff, sg) = GPM·ft·SG/(3960·eff) in BHP, for water unless sg is given. Last input "SI": kW from L/s and m', (a, si) => {
    const eff = efficiency(a[2], 'Pump efficiency');
    const sg = a[3] === undefined ? 1 : pos(num(a[3], 'Specific gravity'), 'Specific gravity');
    return map2(a[0], a[1], (q, h) => (si ? (9.80665e-3 * q * h * sg) / eff : (q * h * sg) / (3960 * eff)), 'pumppower');
  }));
  def('pipevel', withUnits(2, 2, 'pipevel(gpm, d) = 0.4085·GPM/d² in ft/s, d the inside diameter in inches. Last input "SI" for L/s, mm and m/s', (a, si) =>
    map2(a[0], a[1], (q, d) => ((si ? 1273.2395 : 0.408495) * q) / pos(d, 'Pipe diameter') ** 2, 'pipevel')));
  def('pipeloss', withUnits(3, 3, 'pipeloss(gpm, d, c): Hazen-Williams head loss for water in ft per 100 ft. c is 150 for copper, about 100 to 130 for steel. Last input "SI" for L/s, mm and m per 100 m', (a, si) => {
    const c = pos(num(a[2], 'Hazen-Williams C'), 'Hazen-Williams C');
    return map2(a[0], a[1], (q, d) => {
      pos(d, 'Pipe diameter');
      return si
        ? (10.67 * 100 * (q / 1000) ** 1.852) / (c ** 1.852 * (d / 1000) ** 4.8704)
        : (0.2083 * (100 / c) ** 1.852 * q ** 1.852) / d ** 4.8655;
    }, 'pipeloss');
  }));
  def('valvecv', withUnits(2, 3, 'valvecv(gpm, dp, sg) = GPM·√(SG/Δp), Δp in psi. Last input "SI" for Kv from m³/h and bar', (a) => {
    const sg = a[2] === undefined ? 1 : pos(num(a[2], 'Specific gravity'), 'Specific gravity');
    return map2(a[0], a[1], (q, dp) => q * Math.sqrt(sg / pos(dp, 'Pressure drop')), 'valvecv');
  }));
  def('valveflow', withUnits(2, 3, 'valveflow(cv, dp, sg) = Cv·√(Δp/SG) in GPM, Δp in psi. Last input "SI" for m³/h from Kv and bar', (a) => {
    const sg = a[2] === undefined ? 1 : pos(num(a[2], 'Specific gravity'), 'Specific gravity');
    return map2(a[0], a[1], (cv, dp) => {
      if (dp < 0) fail(`Pressure drop can't be negative, got ${dp}`);
      return cv * Math.sqrt(dp / sg);
    }, 'valveflow');
  }));
  def('gasinput', withUnits(2, 3, 'gasinput(volume, seconds, hv): clock a gas meter. Btu/h from ft³ and seconds, heating value 1000 Btu/ft³ unless given. Last input "SI": kW from m³, heating value 37.3 MJ/m³', (a, si) => {
    const hv = a[2] === undefined ? (si ? 37.3 : 1000) : pos(num(a[2], 'Heating value'), 'Heating value');
    return map2(a[0], a[1], (v, s) => (si ? (v * hv * 1000) / pos(s, 'Time') : (3600 * v * hv) / pos(s, 'Time')), 'gasinput');
  }));
  def('elecpower', { min: 2, max: 4, usage: 'elecpower(volts, amps, pf, phases): real power in kW. pf is 1 and phases is 1 unless given; three-phase uses √3', fn: (a) => {
    const pf = a[2] === undefined ? 1 : num(a[2], 'Power factor');
    if (!(pf > 0 && pf <= 1)) fail(`Power factor must be above 0 and at most 1, got ${pf}`);
    const phases = a[3] === undefined ? 1 : num(a[3], 'Phases');
    if (phases !== 1 && phases !== 3) fail(`Phases must be 1 or 3, got ${phases}`);
    const k = phases === 3 ? Math.sqrt(3) : 1;
    return map2(a[0], a[1], (v, i) => (k * v * i * pf) / 1000, 'elecpower');
  } });
  def('voltimbalance', { min: 3, max: 3, usage: 'voltimbalance(a, b, c): percent voltage imbalance, the largest difference from the average over the average', fn: (a) => {
    const v = a.map((x) => pos(num(x, 'Voltage'), 'Voltage'));
    const avg = (v[0] + v[1] + v[2]) / 3;
    return (Math.max(...v.map((x) => Math.abs(x - avg))) / avg) * 100;
  } });

  // Refrigerants
  def('refrigerants', { min: 0, max: 0, usage: 'refrigerants(): every refrigerant with a table', fn: () => list(REFRIGERANTS.map((r) => text(r.name))) });
  const refScalar = (usage: string, what: string, f: (r: RefData, x: number, atm: number, si: boolean) => number): Builtin =>
    withUnits(2, 3, usage, (a, si) => {
      const r = refArg(a[0]);
      const atm = atmKpa(a[2], si);
      return mapNum(a[1], (x) => f(r, x, atm, si), what);
    });
  def('pbubble', refScalar('pbubble("R410A", t, alt): bubble point (liquid) pressure in psig at t °F. Last input "SI" for kPa gauge and °C', 'pbubble', (r, t, atm, si) => absToGauge(satKpa(r, toF(t, si), false), atm, si)));
  def('pdew', refScalar('pdew("R410A", t, alt): dew point (vapor) pressure in psig at t °F. Last input "SI" for kPa gauge and °C', 'pdew', (r, t, atm, si) => absToGauge(satKpa(r, toF(t, si), true), atm, si)));
  def('tbubble', refScalar('tbubble("R410A", p, alt): bubble point (liquid) temperature in °F at p psig. Last input "SI" for °C and kPa gauge', 'tbubble', (r, p, atm, si) => fromF(satF(r, gaugeToAbs(p, atm, si), false), si)));
  def('tdew', refScalar('tdew("R410A", p, alt): dew point (vapor) temperature in °F at p psig. Last input "SI" for °C and kPa gauge', 'tdew', (r, p, atm, si) => fromF(satF(r, gaugeToAbs(p, atm, si), true), si)));
  def('ptchart', withUnits(2, 3, 'ptchart("R410A", t, alt): saturation pressures in psig at t °F. Last input "SI" for kPa gauge and °C', (a, si) => {
    const r = refArg(a[0]), t = num(a[1], 'Temperature'), atm = atmKpa(a[2], si), f = toF(t, si);
    const bubble = satKpa(r, f, false), dew = satKpa(r, f, true);
    const u = si ? 'kPa gauge' : 'psig';
    return record(`${r.name} at ${t} ${si ? '°C' : '°F'}`, rows(
      [`Bubble, liquid (${u})`, round(absToGauge(bubble, atm, si), si ? 1 : 2)],
      [`Dew, vapor (${u})`, round(absToGauge(dew, atm, si), si ? 1 : 2)],
      [`Spread (${si ? 'kPa' : 'psi'})`, round(si ? bubble - dew : (bubble - dew) / PSI, si ? 1 : 2)],
    ));
  }));
  def('sattemp', withUnits(2, 3, 'sattemp("R410A", p, alt): saturation temperatures in °F at p psig, with the glide. Last input "SI" for °C and kPa gauge', (a, si) => {
    const r = refArg(a[0]), p = num(a[1], 'Pressure'), kpa = gaugeToAbs(p, atmKpa(a[2], si), si);
    const bubble = fromF(satF(r, kpa, false), si), dew = fromF(satF(r, kpa, true), si);
    const u = si ? '°C' : '°F';
    return record(`${r.name} at ${p} ${si ? 'kPa gauge' : 'psig'}`, rows(
      [`Bubble, liquid (${u})`, round(bubble, 2)],
      [`Dew, vapor (${u})`, round(dew, 2)],
      [`Glide (${u})`, round(dew - bubble, 2)],
    ));
  }));
  def('superheat', withUnits(3, 4, 'superheat("R410A", p, t, alt): suction line temperature above the dew point, in °F, from p psig and t °F. Last input "SI" for °C and kPa gauge', (a, si) => {
    const r = refArg(a[0]), atm = atmKpa(a[3], si);
    const sat = fromF(satF(r, gaugeToAbs(num(a[1], 'Pressure'), atm, si), true), si);
    return mapNum(a[2], (t) => t - sat, 'superheat');
  }));
  def('subcool', withUnits(3, 4, 'subcool("R410A", p, t, alt): liquid line temperature below the bubble point, in °F, from p psig and t °F. Last input "SI" for °C and kPa gauge', (a, si) => {
    const r = refArg(a[0]), atm = atmKpa(a[3], si);
    const sat = fromF(satF(r, gaugeToAbs(num(a[1], 'Pressure'), atm, si), false), si);
    return mapNum(a[2], (t) => sat - t, 'subcool');
  }));
  def('targetsuperheat', withUnits(2, 2, 'targetsuperheat(iwb, odb) = (3·IWB − 80 − ODB)/2: fixed-orifice target in °F from indoor wet bulb and outdoor dry bulb. Follow the unit\'s own charging chart first. Last input "SI" for °C', (a, si) =>
    map2(a[0], a[1], (iwb, odb) => {
      const f = (3 * toF(iwb, si) - 80 - toF(odb, si)) / 2;
      return si ? (f * 5) / 9 : f;
    }, 'targetsuperheat')));
  def('refprops', withUnits(2, 2, 'refprops("R410A", t): saturated liquid and vapor properties at t °F. Enthalpy and entropy are 0 for saturated liquid at -40 °F. Last input "SI" for °C', (a, si) => {
    const r = refArg(a[0]), t = num(a[1], 'Temperature');
    const s = satState(r, toF(t, si));
    return record(`${r.name} saturated at ${t} ${si ? '°C' : '°F'}`, si
      ? rows(
        ['Bubble pressure (kPa abs)', round(s.pb, 1)],
        ['Dew pressure (kPa abs)', round(s.pd, 1)],
        ['Liquid enthalpy (kJ/kg)', round(s.hl, 2)],
        ['Vapor enthalpy (kJ/kg)', round(s.hv, 2)],
        ['Latent heat (kJ/kg)', round(s.hv - s.hl, 2)],
        ['Liquid entropy (kJ/kg·K)', round(s.sl, 4)],
        ['Vapor entropy (kJ/kg·K)', round(s.sv, 4)],
        ['Liquid density (kg/m³)', round(s.dl, 1)],
        ['Vapor volume (m³/kg)', round(s.vv, 5)],
      )
      : rows(
        ['Bubble pressure (psia)', round(s.pb / PSI, 2)],
        ['Dew pressure (psia)', round(s.pd / PSI, 2)],
        ['Liquid enthalpy (Btu/lb)', round(s.hl / KJKG_PER_BTULB, 2)],
        ['Vapor enthalpy (Btu/lb)', round(s.hv / KJKG_PER_BTULB, 2)],
        ['Latent heat (Btu/lb)', round((s.hv - s.hl) / KJKG_PER_BTULB, 2)],
        ['Liquid entropy (Btu/lb·°R)', round(s.sl / 4.1868, 4)],
        ['Vapor entropy (Btu/lb·°R)', round(s.sv / 4.1868, 4)],
        ['Liquid density (lb/ft³)', round(s.dl / REF_KGM3_PER_LBFT3, 2)],
        ['Vapor volume (ft³/lb)', round(s.vv * REF_KGM3_PER_LBFT3, 4)],
      ));
  }));
  def('refcycle', withUnits(3, 6, 'refcycle("R410A", evap, cond, sh, sc, eff): vapor-compression cycle from evaporating (dew) and condensing (bubble) °F, superheat, subcooling, and compressor isentropic efficiency, ideal unless given. Last input "SI" for °C', (a, si) => {
    const r = refArg(a[0]);
    const te = num(a[1], 'Evaporating temperature'), tc = num(a[2], 'Condensing temperature');
    const dT = (v: Value | undefined, what: string): number => {
      if (v === undefined) return 0;
      const x = num(v, what);
      return si ? (x * 9) / 5 : x;
    };
    const eta = efficiency(a[5], 'Compressor efficiency');
    const c = cycle(r, toF(te, si), toF(tc, si), dT(a[3], 'Superheat'), dT(a[4], 'Subcooling'), eta);
    const cop = c.q / c.w;
    const atm = atmKpa(undefined, si);
    const flow = (si ? 1 / c.q : 200 * KJKG_PER_BTULB / c.q); // kg/s per kW, or lb/min per ton
    const volume = si ? flow * c.v1 * 1000 : flow * c.v1 * REF_KGM3_PER_LBFT3; // L/s per kW, or CFM per ton
    const e = si ? 1 : 1 / KJKG_PER_BTULB;
    const u = si ? 'kJ/kg' : 'Btu/lb';
    const gauge = si ? 'kPa gauge' : 'psig';
    return record(`${r.name}, ${round(eta * 100, 1)}% isentropic`, rows(
      [`Suction (${gauge})`, round(absToGauge(c.pe, atm, si), si ? 0 : 1)],
      [`Discharge (${gauge})`, round(absToGauge(c.pc, atm, si), si ? 0 : 1)],
      ['Compression ratio', round(c.pc / c.pe, 2)],
      [`Refrigeration effect (${u})`, round(c.q * e, 2)],
      [`Compressor work (${u})`, round(c.w * e, 2)],
      [`Heat rejected (${u})`, round((c.q + c.w) * e, 2)],
      ['COP', round(cop, 3)],
      ['EER', round(cop * BTUH_PER_W, 2)],
      ['kW/ton', round(KW_PER_TON / cop, 3)],
      [si ? 'Mass flow (kg/s per kW)' : 'Mass flow (lb/min per ton)', round(flow, si ? 5 : 3)],
      [si ? 'Displacement (L/s per kW)' : 'Displacement (CFM per ton)', round(volume, 3)],
      [`Discharge temperature (${si ? '°C' : '°F'})`, round(fromF(c.dischargeF, si), 1)],
    ));
  }));
  def('carnotcop', withUnits(2, 2, 'carnotcop(evap, cond): the ideal COP between two temperatures in °F. Last input "SI" for °C', (a, si) =>
    map2(a[0], a[1], (te, tc) => {
      const cold = toF(te, si) + 459.67, hot = toF(tc, si) + 459.67;
      if (!(hot > cold && cold > 0)) fail('Condensing must be above evaporating, and both above absolute zero');
      return cold / (hot - cold);
    }, 'carnotcop')));
  def(['eertocop', 'seertocop', 'hspftocop'], { min: 1, max: 1, usage: 'eertocop(eer) = EER ÷ 3.412. SEER and HSPF convert the same way, as seasonal averages', fn: (a) => mapNum(a[0], (x) => x / BTUH_PER_W, 'eertocop') });
  def('coptoeer', { min: 1, max: 1, usage: 'coptoeer(cop) = COP × 3.412', fn: (a) => mapNum(a[0], (x) => x * BTUH_PER_W, 'coptoeer') });
  def('coptokwton', { min: 1, max: 1, usage: 'coptokwton(cop) = 3.517 ÷ COP, in kW per ton', fn: (a) => mapNum(a[0], (x) => KW_PER_TON / pos(x, 'COP'), 'coptokwton') });
  def('kwtontocop', { min: 1, max: 1, usage: 'kwtontocop(kwton) = 3.517 ÷ kW per ton', fn: (a) => mapNum(a[0], (x) => KW_PER_TON / pos(x, 'kW per ton'), 'kwtontocop') });
}
